import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Queue;

import static org.junit.jupiter.api.Assertions.*;

public class MakeColumnQueuesTests {

    private TextStyle createSampleTextStyle() {
        try {
            Constructor<TextStyle> ctor = TextStyle.class.getDeclaredConstructor();
            ctor.setAccessible(true);
            return ctor.newInstance();
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    @Test
    public void testMakeColumnQueuesReturnsCorrectSizeAndDeterministicContent() {
        TextHelpAppendable appendable = new TextHelpAppendable(new StringBuilder());

        List<String> columnData = Arrays.asList("Alpha", "Beta", "Gamma");
        TextStyle style1 = createSampleTextStyle();
        List<TextStyle> styles = Arrays.asList(style1, style1, style1);

        List<Queue<String>> firstResult = appendable.makeColumnQueues(columnData, styles);
        assertNotNull(firstResult);
        assertEquals(columnData.size(), firstResult.size(), "Number of queues should match number of data entries");

        // Ensure each queue is non-null and has content
        for (int i = 0; i < firstResult.size(); i++) {
            Queue<String> q = firstResult.get(i);
            assertNotNull(q, "Queue at index " + i + " should not be null");
            assertFalse(q.isEmpty(), "Queue at index " + i + " should not be empty");
        }

        // Second call with identical inputs should produce identical content (deterministic)
        List<Queue<String>> secondResult = appendable.makeColumnQueues(columnData, styles);
        assertNotNull(secondResult);
        assertEquals(firstResult.size(), secondResult.size(), "Second result should have same number of queues");

        for (int i = 0; i < firstResult.size(); i++) {
            List<String> firstContents = new ArrayList<>();
            for (String s : firstResult.get(i)) {
                firstContents.add(s);
            }

            List<String> secondContents = new ArrayList<>();
            for (String s : secondResult.get(i)) {
                secondContents.add(s);
            }

            assertEquals(firstContents, secondContents, "Contents of queue at index " + i + " should be identical across calls");
        }
    }

    @Test
    public void testMakeColumnQueuesWithMismatchedStylesThrowsIndexOutOfBounds() {
        TextHelpAppendable appendable = new TextHelpAppendable(new StringBuilder());

        List<String> columnData = Arrays.asList("One", "Two");
        TextStyle style = createSampleTextStyle();

        // styles list smaller than columnData list should trigger IndexOutOfBoundsException
        List<TextStyle> styles = Collections.singletonList(style);

        assertThrows(IndexOutOfBoundsException.class, () -> appendable.makeColumnQueues(columnData, styles));
    }

    @Test
    public void testMakeColumnQueuesWithNullInputsThrowsNPE() {
        TextHelpAppendable appendable = new TextHelpAppendable(new StringBuilder());

        List<String> columnData = Arrays.asList("A", "B");
        TextStyle style = createSampleTextStyle();
        List<TextStyle> styles = Arrays.asList(style, style);

        // Null columnData should throw NullPointerException
        assertThrows(NullPointerException.class, () -> appendable.makeColumnQueues(null, styles));

        // Null styles should throw NullPointerException
        assertThrows(NullPointerException.class, () -> appendable.makeColumnQueues(columnData, null));
    }
}

