import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

import java.lang.reflect.Method;

public class PadTests {

    private TextStyle buildWithParams(int width, TextStyle.Alignment align) throws Exception {
        Object builder = TextStyle.builder();
        builder = configure(builder, new String[]{"width","maxWidth","setWidth","setMaxWidth","size","cols","columns"},
                new Class[]{int.class}, new Object[]{width});
        builder = configure(builder, new String[]{"alignment","setAlignment"},
                new Class[]{TextStyle.Alignment.class}, new Object[]{align});
        Method get = builder.getClass().getMethod("get");
        return (TextStyle) get.invoke(builder);
    }

    private TextStyle buildWithParamsIndent(int width, TextStyle.Alignment align, int indent) throws Exception {
        Object builder = TextStyle.builder();
        builder = configure(builder, new String[]{"width","maxWidth","setWidth","setMaxWidth","size","cols","columns"},
                new Class[]{int.class}, new Object[]{width});
        builder = configure(builder, new String[]{"alignment","setAlignment"},
                new Class[]{TextStyle.Alignment.class}, new Object[]{align});
        builder = configure(builder, new String[]{"indent","setIndent"},
                new Class[]{int.class}, new Object[]{indent});
        Method get = builder.getClass().getMethod("get");
        return (TextStyle) get.invoke(builder);
    }

    private Object configure(Object builder, String[] names, Class<?>[] paramTypes, Object[] args) throws Exception {
        for (String name : names) {
            for (Method m : builder.getClass().getMethods()) {
                if (m.getName().equals(name) && m.getParameterTypes().length == paramTypes.length) {
                    Class<?>[] ptypes = m.getParameterTypes();
                    boolean ok = true;
                    for (int i = 0; i < ptypes.length; i++) {
                        Class<?> pt = ptypes[i];
                        Class<?> at = paramTypes[i];
                        if (!isCompatible(pt, at)) {
                            ok = false;
                            break;
                        }
                    }
                    if (ok) {
                        Object result = m.invoke(builder, args);
                        if (result != null) {
                            builder = result;
                        }
                        return builder;
                    }
                }
            }
        }
        return builder;
    }

    private boolean isCompatible(Class<?> target, Class<?> given) {
        if (target.isAssignableFrom(given)) return true;
        if (target == int.class && given == Integer.class) return true;
        if (target == Integer.class && given == int.class) return true;
        return false;
    }

    @Test
    void padLeftAlignmentNoIndentPadsToWidth() throws Exception {
        TextStyle ts = buildWithParams(5, TextStyle.Alignment.LEFT);
        CharSequence res = ts.pad(false, "a");
        assertEquals("a    ", res.toString());
