        OptionGroup group = new OptionGroup();
        group.addOption(opt);
        group.setRequired(true);

        Options result = options.addOptionGroup(group);

        assertSame(options, result, "addOptionGroup should return the current Options instance for chaining");
    }

    @Test
    void addOptionGroup_RequiredGroup_MarksMemberAsNotRequired() {
        Options options = new Options();
        Option opt = new Option("a", "alpha", false, "Alpha");
        OptionGroup group = new OptionGroup();
        group.addOption(opt);
        group.setRequired(true);

        options.addOptionGroup(group);

        assertFalse(opt.isRequired(), "Option inside a required group should not be individually required");
    }

    @Test
    void addOptionGroup_ParsesSingleMemberFromGroup() throws Exception {
        Options options = new Options();
        Option optA = new Option("a", "alpha", false, "Alpha");
        Option optB = new Option("b", "beta", false, "Beta");
        OptionGroup group = new OptionGroup();
        group.addOption(optA);
        group.addOption(optB);
        group.setRequired(true);
        options.addOptionGroup(group);

        DefaultParser parser = new DefaultParser();
        CommandLine cl = parser.parse(options, new String[]{"-a"});

        assertTrue(cl.hasOption("a"));
        assertFalse(cl.hasOption("b"));
    }

